"</svg>\n"
"\n"
"<main id=\"composer\" class=\"flex flex-col gap-3 px-4 pt-[max(12px,env(safe-area-inset-top))] pb-4\">\n"
"  <header class=\"flex items-center gap-2\">\n"
"    <img src=\"/favicon.png\" alt=\"\" class=\"size-7 rounded-md\">\n"
"    <h1 class=\"text-lg font-semibold tracking-tight whitespace-nowrap\">Kindle Terminal</h1>\n"
"    <p id=\"state\" class=\"ml-auto min-w-0 truncate text-right text-xs text-neutral-500\">正在连接…</p>\n"
"  </header>\n"
"  <textarea id=\"text\" rows=\"3\"\n"
"    class=\"h-28 w-full resize-none rounded-xl border border-neutral-300 bg-white px-3 py-2.5 text-[17px] leading-relaxed shadow-sm outline-none placeholder:text-neutral-400 focus:border-neutral-900 focus:ring-2 focus:ring-neutral-900/10 dark:border-neutral-700 dark:bg-neutral-900 dark:focus:border-neutral-300 dark:focus:ring-white/10\"\n"
"    placeholder=\"用键盘上的麦克风说，或者直接打字，改好了再发送\"></textarea>\n"
"  <div class=\"grid grid-cols-2 gap-2\">\n"
"    <button id=\"send\" class=\"btn border-neutral-900 bg-neutral-900 text-white dark:border-white dark:bg-white dark:text-neutral-900\">\n"
"      <svg class=\"icon\"><use href=\"#i-send\"/></svg>发送</button>\n"
"    <button id=\"run\" class=\"btn\">\n"
"      <svg class=\"icon\"><use href=\"#i-run\"/></svg>发送并回车</button>\n"
"    <button id=\"enter\" class=\"btn\">\n"
"      <svg class=\"icon\"><use href=\"#i-enter\"/></svg>回车</button>\n"
"    <button id=\"clear\" class=\"btn\">\n"
"      <svg class=\"icon\"><use href=\"#i-clear\"/></svg>清空</button>\n"
"  </div>\n"
"</main>\n"
"\n"
"<section class=\"px-4 pb-[max(24px,env(safe-area-inset-bottom))]\">\n"
"  <h2 class=\"mb-2 flex items-baseline gap-2 text-sm font-semibold text-neutral-500\">最近发送<span id=\"count\" class=\"font-normal\"></span></h2>\n"
"  <p id=\"empty\" class=\"text-sm leading-relaxed text-neutral-400\">发送过的文字会留在这里（最近 50 条，只存在这台手机上）。点一条填回输入框，连点几条会一行一条接在一起。</p>\n"
"  <ul id=\"history\" class=\"flex flex-col gap-2\"></ul>\n"
"</section>\n"
"\n"
"<div id=\"toast\" class=\"pointer-events-none fixed inset-x-0 bottom-[max(20px,env(safe-area-inset-bottom))] mx-auto w-fit max-w-[90vw] rounded-full bg-neutral-900 px-4 py-2 text-sm text-white opacity-0 shadow-lg transition-opacity duration-200 dark:bg-white dark:text-neutral-900\"></div>\n"
"\n"
"<template id=\"item\">\n"
"  <li class=\"flex items-stretch rounded-xl border border-neutral-200 bg-white shadow-sm transition-shadow dark:border-neutral-800 dark:bg-neutral-900\">\n"
"        <button data-act=\"fill\" class=\"min-w-0 flex-1 px-3 py-2.5 text-left\">\n"
"      <span class=\"line-clamp-3 text-[15px] leading-snug break-words whitespace-pre-wrap\"></span>\n"
"    </button>\n"
"    <div class=\"flex shrink-0 items-center pr-1\">\n"
"      <button data-act=\"send\" aria-label=\"发送\" class=\"icon-btn\"><svg class=\"icon\"><use href=\"#i-send\"/></svg></button>\n"
"      <button data-act=\"run\" aria-label=\"发送并回车\" class=\"icon-btn\"><svg class=\"icon\"><use href=\"#i-run\"/></svg></button>\n"
"      <button data-act=\"copy\" aria-label=\"复制\" class=\"icon-btn\"><svg class=\"icon\"><use href=\"#i-copy\"/></svg></button>\n"
"    </div>\n"
"  </li>\n"
"</template>\n"
"\n"
"<script>\n"
"const base = location.pathname.replace(/\\/+$/, '');\n"
"const $ = id => document.getElementById(id);\n"
"const text = $('text'), state = $('state'), list = $('history'), composer = $('composer');\n"
"/** Entries kept */\n"
"const LIMIT = 50;\n"
"\n"
"// ---- sending ----\n"
"\n"
"/** The line under the title: whether the Kindle is there */\n"
"function show(ok, message) {\n"
"  state.classList.toggle('text-emerald-600', ok);\n"
"  state.classList.toggle('text-red-600', !ok);\n"
"  state.textContent = message;\n"
"}\n"
"\n"
"async function ping() {\n"
"  try {\n"
"    const r = await fetch(base + '/ping', {cache: 'no-store'});\n"
"    if (r.ok) show(true, '已连接 Kindle');\n"
"    else show(false, r.status == 403 ? '口令不对：请重新扫 Kindle 上的二维码' : 'Kindle 出错了（' + r.status + '）');\n"
"  } catch (e) {\n"
"    show(false, '连不上 Kindle：kterm 开着吗？语音输入打开了吗？');\n"
"  }\n"
"}\n"
"\n"
"/** What the Kindle did with the text, see voicebar.c */\n"
"const done = {\n"
"  staged: '已放进 Kindle 键盘上方的框里',\n"
"  ran: '已放入并回车',\n"
"  'staged-run': 'Kindle 正往上翻：已放进框里，点一下就执行',\n"
"};\n"
"\n"
"/**\n"
" * @param value Text, may be empty\n"
" * @param run Enter after it\n"
" * @return true if the Kindle took it\n"
" */\n"
"async function send(value, run) {\n"
"  try {\n"
"    const r = await fetch(base + '/send' + (run ? '?run=1' : ''), {\n"
"      method: 'POST', body: value, headers: {'Content-Type': 'text/plain;charset=utf-8'}});\n"
"    if (!r.ok) throw new Error(r.status);\n"
"    const status = await r.text();\n"
"    show(true, '已连接 Kindle');\n"
"    // what became of it: told once, for a moment\n"
"    toast(done[status] || 'Kindle 没有回应，文字可能没放进去');\n"
"    return !!done[status];\n"
"  } catch (e) {\n"
"    show(false, '没发出去：连不上 Kindle');\n"
"    toast('没发出去：连不上 Kindle');\n"
"    return false;\n"
"  }\n"
"}\n"
"\n"
"async function sendText(run) {\n"
"  const value = text.value;\n"
"  if (!value && !run) return;\n"
"  if (await send(value, run)) {\n"
"    remember(value);\n"
"    // not if more was typed meanwhile\n"
"    if (text.value === value) { text.value = ''; localStorage.removeItem('draft'); }\n"
"  }\n"
"}\n"
"\n"
"// ---- history, kept in this browser ----\n"
"\n"
"function load() {\n"
"  try {\n"
"    const h = JSON.parse(localStorage.getItem('history') || '[]');\n"
"    return Array.isArray(h) ? h.filter(x => typeof x === 'string') : [];\n"
"  } catch (e) { return []; }\n"
"}\n"
"let history = load();\n"
"\n"
"/** The newest first; the same text once */\n"
"function remember(value) {\n"
"  if (!value.trim()) return;\n"
"  history = [value, ...history.filter(x => x !== value)].slice(0, LIMIT);\n"
"  localStorage.setItem('history', JSON.stringify(history));\n"
"  render();\n"
"}\n"
"\n"
"function render() {\n"
"  const template = $('item');\n"
"  list.replaceChildren(...history.map((value, index) => {\n"
"    const li = template.content.firstElementChild.cloneNode(true);\n"
"    li.dataset.index = index;\n"
"    li.querySelector('[data-act=fill] span').textContent = value;\n"
"    return li;\n"
"  }));\n"
"  $('count').textContent = history.length ? history.length + ' 条' : '';\n"
"  $('empty').hidden = history.length > 0;\n"
"}\n"
"\n"
"/** Put an entry back in the box: after what is there, a line of its own */\n"
"function fill(value) {\n"
"  text.value = text.value ? text.value.replace(/\\n*$/, '\\n') + value : value;\n"
"  localStorage.setItem('draft', text.value);\n"
"  toast('已填回输入框');\n"
"}\n"
"\n"
"/** Copy to the clipboard; the page is not https, so the old way if need be */\n"
"async function copy(value) {\n"
"  try {\n"
"    if (navigator.clipboard && window.isSecureContext) {\n"
"      await navigator.clipboard.writeText(value);\n"
"      return true;\n"
"    }\n"
"  } catch (e) {}\n"
"  const area = document.createElement('textarea');\n"
"  area.value = value;\n"
"  area.setAttribute('readonly', '');\n"
"  area.style.cssText = 'position:fixed;top:0;left:0;opacity:0;font-size:16px';\n"
"  document.body.append(area);\n"
"  area.select();\n"
"  area.setSelectionRange(0, value.length);\n"
"  let ok = false;\n"
"  try { ok = document.execCommand('copy'); } catch (e) {}\n"
"  area.remove();\n"
"  return ok;\n"
"}\n"
"\n"
"list.addEventListener('click', async e => {\n"
"  const button = e.target.closest('button[data-act]');\n"
"  const li = button && button.closest('li');\n"
"  if (!li) return;\n"
"  const value = history[li.dataset.index];\n"
"  if (value === undefined) return;\n"
"  const act = button.dataset.act;\n"
"  if (act === 'fill') {\n"
"    fill(value);\n"
"    li.classList.add('ring-2', 'ring-neutral-900', 'dark:ring-white');\n"
"    setTimeout(() => li.classList.remove('ring-2', 'ring-neutral-900', 'dark:ring-white'), 600);\n"
"  } else if (act === 'send' || act === 'run') {\n"
"    if (await send(value, act === 'run')) remember(value);\n"
"  } else if (act === 'copy') {\n"
"    const ok = await copy(value);\n"
"    toast(ok ? '已复制' : '复制失败');\n"
"    if (ok) {\n"
"      const use = button.querySelector('use');\n"
"      use.setAttribute('href', '#i-check');\n"
"      setTimeout(() => use.setAttribute('href', '#i-copy'), 1500);\n"
"    }\n"
"  }\n"
"});\n"
"\n"
"// ---- the page ----\n"
"\n"
"let toastTimer = 0;\n"
"function toast(message) {\n"
"  const t = $('toast');\n"
"  t.textContent = message;\n"
"  t.classList.remove('opacity-0');\n"
"  clearTimeout(toastTimer);\n"
"  toastTimer = setTimeout(() => t.classList.add('opacity-0'), 1800);\n"
"}\n"
"\n"
"/* The text box takes at most about a third of the screen; with the\n"
"   keyboard out, what is left above it, so that the buttons are never\n"
"   covered. The list below may be: the page scrolls to it. */\n"
"let tallest = window.innerHeight;\n"
"function fit() {\n"
"  const v = window.visualViewport;\n"
"  const visible = v ? v.height : window.innerHeight;\n"
"  tallest = Math.max(tallest, window.innerHeight);\n"
"  const others = composer.offsetHeight - text.offsetHeight;\n"
"  const height = Math.min(Math.round(tallest * 0.3), visible - others);\n"
"  text.style.height = Math.max(64, height) + 'px';\n"
"  if (document.activeElement === text) window.scrollTo(0, 0);\n"
"}\n"
"if (window.visualViewport) visualViewport.addEventListener('resize', fit);\n"
"window.addEventListener('resize', fit);\n"
"text.addEventListener('focus', () => setTimeout(fit, 350));\n"
"\n"
"// a tap on a button keeps the keyboard up: the focus stays in the box\n"
"for (const button of composer.querySelectorAll('button')) {\n"
"  button.addEventListener('pointerdown', e => { if (document.activeElement === text) e.preventDefault(); });\n"
"}\n"
"$('send').onclick = () => sendText(false);\n"
"$('run').onclick = () => sendText(true);\n"
"$('enter').onclick = () => send('', true);\n"
"$('clear').onclick = () => { text.value = ''; localStorage.removeItem('draft'); };\n"
"\n"
"text.value = localStorage.getItem('draft') || '';\n"
"text.addEventListener('input', () => localStorage.setItem('draft', text.value));\n"
"document.addEventListener('visibilitychange', () => { if (!document.hidden) ping(); });\n"
"setInterval(() => { if (!document.hidden) ping(); }, 15000);\n"
"render();\n"
"fit();\n"
"ping();\n"
"</script>\n"
"</body>\n"
"</html>\n";
#pragma GCC diagnostic pop

#endif /* voice_page_h */
